import readline from 'node:readline/promises';import {stdin,stdout} from 'node:process';import {randomUUID} from 'node:crypto';import {hashPassword} from '../src/utils/passwords.js';import {db,migrate} from '../src/database/index.js';import {env} from '../src/config/env.js';
migrate();const rl=readline.createInterface({input:stdin,output:stdout});try{const email=env.ADMIN_BOOTSTRAP_EMAIL||await rl.question('Administrator email: ');const name=await rl.question('Administrator display name: ');const password=await rl.question('Use a unique password of at least 16 characters: ');if(password.length<16)throw new Error('Password must be at least 16 characters');if(db.prepare("SELECT count(*) n FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE r.name='administrator'").get().n)throw new Error('An administrator already exists');const id=randomUUID(),hash=await hashPassword(password);db.transaction(()=>{db.prepare('INSERT INTO users(id,email,password_hash,display_name,email_verified_at) VALUES(?,?,?,?,CURRENT_TIMESTAMP)').run(id,email,name,hash);db.prepare("INSERT INTO user_roles(user_id,role_id) SELECT ?,id FROM roles WHERE name='administrator'").run(id)})();console.log(`Administrator ${email} created. Store credentials securely.`)}finally{rl.close();db.close()}
